from functools import lru_cache

@lru_cache(maxsize=128)
def fib(n: int) -> int:
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

class Counter:
    def __init__(self):
        self.n = 0
    def inc(self):
        self.n += 1
    def value(self):
        return self.n

def even_squares(xs):
    return [x * x for x in xs if x % 2 == 0]

def char_freq(s):
    return {c: s.count(c) for c in set(s)}

def find(xs, target):
    for i, x in enumerate(xs):
        if x == target:
            return i
    return -1

def safe_div(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return 0

def render_dashboard(metrics):
    lines = []
    lines.append('=== Dashboard ===')
    for k, v in metrics.items():
        if isinstance(v, (int, float)):
            lines.append(f'{k:>20}: {v:>10.2f}')
        else:
            lines.append(f'{k:>20}: {v}')
    if 'errors' in metrics and metrics['errors'] > 0:
        lines.append('!! Errors detected; check logs.')
    elif 'warnings' in metrics and metrics['warnings'] > 0:
        lines.append('* Warnings present.')
    else:
        lines.append('OK')
    return '\n'.join(lines)
